use crate::{
    RepoPath, STANDARD_GENERATED_MARKERS, SourceSet, contains_ascii_ignore_case,
    has_any_ascii_marker, has_folder_named, has_generated_header_marker,
    has_generated_header_marker_with_extra, path_file_name, settle_source_set,
};

#[test]
fn standard_generated_header_markers_match_case_insensitively() {
    assert_eq!(STANDARD_GENERATED_MARKERS.len(), 6);
    for sample in [
        "// @generated",
        "/* @GENERATED SignedSource<<0123abcd>> */",
        "// This file is auto-generated.",
        "// AUTOGENERATED FILE",
        "/**\n * This file was automatically generated by schema-tool.\n */",
        "// Code generated by protoc. DO NOT EDIT.",
        "// Generated by CoffeeScript 1.12.7",
        "// 日本語 - @GeNeRaTeD - テスト",
    ] {
        assert!(
            has_generated_header_marker(sample),
            "expected generated marker in {sample:?}"
        );
    }
}

#[test]
fn non_generated_comments_do_not_match_standard_generated_header_markers() {
    for sample in [
        "",
        "// The generator of this report reads the config.",
        "// Generates the next id, so edit with care.",
        "// generated code",
        "// auto generated file",
        "// do not modify by hand",
        "// regular license header",
    ] {
        assert!(
            !has_generated_header_marker(sample),
            "unexpected generated marker in {sample:?}"
        );
    }
}

#[test]
fn generated_header_marker_with_extra_matches_both_standard_and_extra_markers() {
    assert!(has_generated_header_marker_with_extra(
        "/* NOTE: This class is auto generated by OpenAPI Generator. */",
        &["auto generated"]
    ));
    assert!(has_generated_header_marker_with_extra(
        "// AUTO GENERATED",
        &["auto generated"]
    ));
    assert!(has_generated_header_marker_with_extra(
        "// @generated",
        &["auto generated"]
    ));
    assert!(!has_generated_header_marker_with_extra(
        "// ordinary comment",
        &["auto generated"]
    ));
    assert!(!has_generated_header_marker_with_extra(
        "// auto generated",
        &[]
    ));
}

#[test]
fn has_any_ascii_marker_and_contains_ascii_ignore_case_handle_edge_cases() {
    let dart_markers = ["generated code", "do not modify by hand"];
    assert!(has_any_ascii_marker(
        "// GENERATED CODE - DO NOT MODIFY BY HAND\n",
        &dart_markers
    ));
    assert!(!has_any_ascii_marker("", &dart_markers));
    assert!(!has_any_ascii_marker("// @generated", &[]));
    assert!(!contains_ascii_ignore_case("short", "longer marker"));
    assert!(contains_ascii_ignore_case("Do Not Edit", "DO NOT EDIT"));
    assert!(contains_ascii_ignore_case("anything", ""));
    assert!(contains_ascii_ignore_case(
        "émoji 🎉 do not edit",
        "DO NOT EDIT"
    ));
}

#[test]
fn has_folder_named_matches_only_exact_directory_segments_at_any_depth() {
    let folders = ["test", "tests", "__tests__"];
    for matching in [
        "test/app.rs",
        "tests/integration.rs",
        "packages/app/tests/unit.ts",
        "src/__tests__/helpers/fixture.js",
    ] {
        assert!(
            has_folder_named(matching, &folders),
            "expected folder match for {matching:?}"
        );
    }
    for non_matching in [
        "",
        "tests.rs",
        "src/tests",
        "src/test.ts",
        "src/my_tests/app.rs",
        "src/testing/app.rs",
        "src/Tests/app.rs",
    ] {
        assert!(
            !has_folder_named(non_matching, &folders),
            "unexpected folder match for {non_matching:?}"
        );
    }
    assert!(!has_folder_named("tests/app.rs", &[]));
}

#[test]
fn path_file_name_returns_final_segment_for_nested_and_root_paths() {
    assert_eq!(path_file_name("src/app/main.rs"), "main.rs");
    assert_eq!(path_file_name("main.rs"), "main.rs");
    assert_eq!(path_file_name(""), "");
}

#[test]
fn settle_source_set_applies_vendored_then_generated_then_plugin_precedence() {
    let path = |raw: &str| RepoPath::new(raw).expect("valid repo path");
    assert_eq!(
        settle_source_set(&path("vendor/dist/lib.js"), "x\n", SourceSet::Test),
        SourceSet::Vendored
    );
    assert_eq!(
        settle_source_set(&path("a/third_party/b.rs"), "x\n", SourceSet::Production),
        SourceSet::Vendored
    );
    assert_eq!(
        settle_source_set(
            &path("packages/app/dist/out.js"),
            "x\n",
            SourceSet::Production
        ),
        SourceSet::Generated
    );
    let minified = format!("{}\r\n", "a".repeat(251));
    assert_eq!(
        settle_source_set(&path("src/bundle.js"), &minified, SourceSet::Production),
        SourceSet::Generated
    );
    assert_eq!(
        settle_source_set(
            &path("src/vendor.ts"),
            "export const x = 1;\n",
            SourceSet::Test
        ),
        SourceSet::Test
    );
}
